import{_ as r,a as n,b as i}from"./chunks/creator-douyin.CkfrT4wq.js";import{_ as s,o as l,c as d,a5 as t,j as e,a as o}from"./chunks/framework.bIR-4glx.js";const h="/up/assets/cover-portrait-en.png",k=JSON.parse('{"title":"Still Here: A Field Guide to Beginning Again","description":"A bilingual open manuscript about failure, recovery, and relearning — with English, AI, real work, and evidence, from Life Level-up Guide.","frontmatter":{"title":"Still Here: A Field Guide to Beginning Again","description":"A bilingual open manuscript about failure, recovery, and relearning — with English, AI, real work, and evidence, from Life Level-up Guide.","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"en/index.md","filePath":"en/README.md","lastUpdated":1795392000000}'),c={name:"en/index.md"};function u(p,a,g,f,y,m){return l(),d("div",null,[...a[0]||(a[0]=[t('<h1 id="still-here" tabindex="-1">Still Here <a class="header-anchor" href="#still-here" aria-label="Permalink to &quot;Still Here&quot;">​</a></h1><p><a href="./../">中文</a> | English</p><p><strong>By Han Xiankai</strong></p><p><strong>A Field Guide to Beginning Again.</strong></p><img src="'+h+'" alt="Still Here: A Field Guide to Beginning Again cover" width="360" height="576"><p>This is not a book about winning. It is one ordinary person&#39;s account of how to stop falling after a company collapses, a body breaks, and relationships strain — and then how to begin learning again through English, AI, real work, and ninety days that answer to evidence.</p><p>There is no curve that only rises. There is failure, insomnia, going home, doctors, and apologies; there are also pages read again, sentences written, and small things delivered. Progress, most of the time, means sweeping the floor, saying what needs to be said, and finishing the next step that can honestly be finished today.</p><p><strong>What this book is:</strong> a bilingual manuscript centred on recovery, a testable learning method, a set of copyable worksheets, and a path that starts at five minutes, retests by chapter, and looks back after ninety days.</p><p><strong>What it is not:</strong> a success formula, medical or therapeutic advice, or a course that requires you to check in.</p><div class="book-meta" aria-label="Book information"><span>First edition 1.1.0 · continuously updated</span><a href="./book-downloads">Download center</a><a href="../public/downloads/life-level-up-guide-en.epub" download>Download English EPUB</a><a href="../public/downloads/life-level-up-guide-zh.epub" download>下载中文 EPUB</a><a href="../public/downloads/life-level-up-guide-en.pdf" download>Download English PDF</a><a href="../public/downloads/life-level-up-guide-zh.pdf" download>下载中文 PDF</a><a href="https://github.com/byoungd/up">Source and corrections</a><a href="./templates/reader-field-note">Reader field note</a><a href="https://github.com/byoungd/up/blob/main/CITATION.cff">Citation format</a><a href="https://creativecommons.org/licenses/by-nc/4.0/">Text CC BY-NC 4.0</a></div><div class="quick-start" aria-labelledby="quick-start-title-en"><div class="quick-start-heading"><span class="quick-start-kicker">Start here</span><h2 id="quick-start-title-en">Choose one entrance; do not move the whole book into today</h2><p>If this is your first visit, choose the entrance closest to where you are, finish one small thing, and let the result point to the next page.</p></div><div class="quick-start-actions"><a class="quick-start-action" href="./threads/part-0/prologue"><strong>Read the prologue: it begins with a fall</strong><span>A hot-pot restaurant in 2022, a frozen bank card, and the room back home that became the real starting point.</span></a><a class="quick-start-action" href="./threads/part-2/my-story"><strong>Read my story</strong><span>A failed company, a body out of control, strained relationships, and how starting again actually looked.</span></a><a class="quick-start-action" href="./reference/reading-map"><strong>Enter by the problem in front of you</strong><span>Seven doorways: restarting, one English skill, an overseas job, resources without artifacts, records without change, helping a learner, low capacity.</span></a></div><p class="quick-start-cycle">Want a full cycle? Start with the <a href="./templates/90-day-cycle">90-Day Cycle Map</a> and bring one practice into real work and life.</p></div><h2 id="who-this-book-is-for" tabindex="-1">Who This Book Is For <a class="header-anchor" href="#who-this-book-is-for" aria-label="Permalink to &quot;Who This Book Is For&quot;">​</a></h2><ul><li>People who want to begin again and do not know which page to start from;</li><li>Self-directed learners who need English for real tasks, not only an exam guide;</li><li>People using AI for real work who do not want to hand over judgment, sources, and privacy with it;</li><li>People coming out of failure, interruption, or a long low season, who need to catch themselves first;</li><li>Parents and teachers who want to support a learner without imposing an adult&#39;s pace.</li></ul><p>If you are looking for a quick formula, a complete English curriculum, or clinical treatment advice, this may not be the right entrance. The full boundaries are in <a href="./threads/part-0/for-whom">Who This Book Is For — and Not For</a>.</p><h2 id="how-the-book-unfolds" tabindex="-1">How the Book Unfolds <a class="header-anchor" href="#how-the-book-unfolds" aria-label="Permalink to &quot;How the Book Unfolds&quot;">​</a></h2><p>The book follows one route you can travel in both directions: catch yourself first, learn again, let tools amplify what you can do, and entrust the change to time.</p><table tabindex="0"><thead><tr><th>Part</th><th>The question it asks</th><th>Representative entry</th></tr></thead><tbody><tr><td>Prologue and how to read</td><td>Where do I enter, and why would I begin again?</td><td><a href="./threads/part-0/prologue">Prologue</a> · <a href="./threads/part-0/reader-guide">How to Read This Book</a></td></tr><tr><td>Part I: Return to Life</td><td>How do failure, the body, relationships, work, and choice fit back into one life?</td><td><a href="./threads/part-2/return-to-life">Part introduction</a> · <a href="./threads/part-2/my-story">My Story</a></td></tr><tr><td>Part II: Learning Again, Opening Input</td><td>How do I rebuild learning through English as one concrete training ground?</td><td><a href="./threads/part-1/open-input">Part introduction</a> · <a href="./threads/part-1/0-cefr">CEFR self-check</a></td></tr><tr><td>Part III: Amplify Ability</td><td>How do I use AI without outsourcing attention and judgment?</td><td><a href="./threads/part-3/1-ai-learning">Learning Anything with AI</a> · <a href="./threads/part-3/5-evidence-and-transfer">Evidence</a></td></tr><tr><td>Part IV: Practice and Recovery</td><td>How does learning return to the body, the family, and the day?</td><td><a href="./threads/part-4/practice-and-recovery">Part introduction</a> · <a href="./threads/part-4/week-1">First week</a></td></tr><tr><td>Part V: Long-Term Action</td><td>How does one cycle enter real work and still echo after ninety days?</td><td><a href="./threads/part-5/long-term-action">Part introduction</a> · <a href="./threads/part-5/90-day-plan">90-Day Action Plan</a></td></tr><tr><td>Part VI and Afterword</td><td>How do I understand, care for, improve, and stay with myself?</td><td><a href="./threads/part-6/1-understanding-yourself">Being Your Own Lifelong Friend</a> · <a href="./threads/part-6/afterword">Afterword</a></td></tr></tbody></table><p>When a term is unclear, open the <a href="./reference/glossary">Glossary</a>. To enter by one problem, open the <a href="./reference/reading-map">Reading Map</a>; the full structure and three reading routes are in the <a href="./threads/part-0/roadmap">Book Roadmap</a>.</p><h2 id="bring-one-page-back-to-today" tabindex="-1">Bring One Page Back to Today <a class="header-anchor" href="#bring-one-page-back-to-today" aria-label="Permalink to &quot;Bring One Page Back to Today&quot;">​</a></h2><p>Lifelong learning is not opening ten courses at once. It is letting one page become a small reality today:</p><ol><li><strong>Write down the problem in front of you.</strong> In <a href="./templates/learning-state">Learning State</a>, record what you already know, what is missing, and what counts as complete. If the problem concerns capacity, relationships, or recovery, use the <a href="./templates/life-practice-toolkit">Life Practice Toolkit</a>.</li><li><strong>Complete one visible action.</strong> Ask AI to help break it down, but check the sources and make the choice yourself. Leave notes, code, a recording, an email, feedback, or another real output — not only a saved chat.</li><li><strong>Come back and check whether it actually carried anything.</strong> Retest on the chapter&#39;s cycle, then use the <a href="./templates/weekly-review">Weekly Review</a> or the <a href="./templates/90-day-cycle">90-Day Cycle Map</a> to decide whether the next step is worth continuing.</li></ol><p>If you find an error, a translation difference, or a reproducible result, tell us through the <a href="https://github.com/byoungd/up/issues/new/choose" target="_blank" rel="noreferrer">issue templates</a>. If this guide helped you finish something real, you can also <a href="https://github.com/byoungd/up" target="_blank" rel="noreferrer">star the repository</a> so more learners can find it.</p><h2 id="for-those-still-on-the-way" tabindex="-1">For Those Still on the Way <a class="header-anchor" href="#for-those-still-on-the-way" aria-label="Permalink to &quot;For Those Still on the Way&quot;">​</a></h2><h3 id="for-younger-readers" tabindex="-1">For Younger Readers <a class="header-anchor" href="#for-younger-readers" aria-label="Permalink to &quot;For Younger Readers&quot;">​</a></h3><p>You do not have to find a permanently correct direction in your twenties. Many directions appear only after a few small projects, several kinds of work, and a few results you had to carry. More reliable than choosing a perfect track is keeping the ability to learn, deliver, and turn.</p><p>If career anxiety keeps you collecting courses, certificates, and success stories, try a two-week project instead: solve one problem for someone near you, build one tool that runs, finish one article with sources, or improve one process for a real user. The project may fail, but it will tell you what you like, what you lack, whether you can deliver, and whether anyone wants to use it again.</p><h3 id="for-those-in-a-low-season" tabindex="-1">For Those in a Low Season <a class="header-anchor" href="#for-those-in-a-low-season" aria-label="Permalink to &quot;For Those in a Low Season&quot;">​</a></h3><p>Job loss, a failed venture, the end of a relationship, damaged health, and long confusion all take a real toll. A low season is not an exam you must win immediately. What you can do today may be sleeping one relatively complete night, eating a meal, going outside, or telling one trusted person, “I need help now.” These things matter on their own. They do not have to be packaged first as a growth report.</p><p>A pause is not giving up, asking for help is not weakness, and recalibrating is not going backwards. When strength returns, decide whether to add weight. The personal stories here are not medical or therapeutic advice. If low mood, insomnia, despair, or dangerous thoughts persist, contact someone you trust and seek qualified local medical or psychological support. Safety first; growth after.</p><h2 id="author-and-real-practice" tabindex="-1">Author and Real Practice <a class="header-anchor" href="#author-and-real-practice" aria-label="Permalink to &quot;Author and Real Practice&quot;">​</a></h2><p>My name is Han Xiankai. This project began in 2017 as the <em>Ridiculous English Learning Guide</em> and later entered learning, development, enterprise services, business experiments, and ordinary life. The methods are tested in these settings, while identity, commercial relationships, capability, and revenue remain explicit. The evidence is the work, the users, the cost, and the time.</p><p>A method only proves itself when it enters life. Relationships end and may begin again; work changes; learning gains new meaning when it meets real people.</p><p>Products, company visits, and real projects are collected in <a href="./projects">Author Projects and Practice</a>, where the author&#39;s involvement, purpose, update date, and non-sponsorship are labelled. Third-party entry points are in the <a href="./resources">resource directory</a>; they are optional and do not imply that the book or the author endorses their safety, quality, or compliance.</p>',33),e("div",{class:"latest-updates"},[e("figure",{class:"latest-update"},[e("img",{src:r,alt:"Han Xiankai and his partner at their fourth wedding",width:"1320",height:"1642",loading:"lazy",decoding:"async",fetchpriority:"low"}),e("figcaption",null,[e("strong",null,"Fourth wedding photo"),o("On love and marriage: love is not only a moment of feeling, but the daily choosing, respecting, carrying, and growing together.")])]),e("figure",{class:"latest-update"},[e("img",{class:"latest-update-visit-photo",src:n,alt:"Han Xiankai visiting a Qwen model demonstration at Alibaba",width:"1706",height:"1279",loading:"lazy",decoding:"async",fetchpriority:"low"}),e("figcaption",null,[e("strong",null,"Visiting Alibaba"),o("A study visit in Hangzhou, where I saw the Qwen model demonstration on site.")])])],-1),t('<h3 id="continue-on-douyin" tabindex="-1">Continue on Douyin <a class="header-anchor" href="#continue-on-douyin" aria-label="Permalink to &quot;Continue on Douyin&quot;">​</a></h3><p>Scan the code to follow the Douyin account <strong>法海韩先凯 (Douyin ID: 72581209403)</strong> for short content on English practice, AI collaboration, real projects, and beginning again. The QR code only points to a public account; this site has no advertising, analytics scripts, or trackers, and the code collects no visitor data. Without a camera, search the name or the ID <code>72581209403</code> in Douyin.</p><figure class="author-social-card"><img src="'+i+'" alt="Douyin account QR code: follow the author for English, AI, and growth practice" width="360" height="538" loading="lazy" decoding="async"><figcaption>Public account QR code provided by the author; image metadata has been removed.</figcaption></figure><h2 id="reading-downloads-and-shared-revision" tabindex="-1">Reading, Downloads, and Shared Revision <a class="header-anchor" href="#reading-downloads-and-shared-revision" aria-label="Permalink to &quot;Reading, Downloads, and Shared Revision&quot;">​</a></h2><ul><li>This is an open-content project, not OSI open source: the text and author content are <strong>CC BY-NC 4.0</strong>; site configuration, checks, and build scripts are <strong>MIT</strong>. See the <a href="https://github.com/byoungd/up/blob/main/LICENSE.md" target="_blank" rel="noreferrer">licence notes</a>.</li><li>Sources, images, and third-party material and their permission status are recorded in <a href="https://github.com/byoungd/up/blob/main/ATTRIBUTIONS.md" target="_blank" rel="noreferrer">ATTRIBUTIONS</a>; the consolidated list is the appendix <a href="./reference/bibliography">Bibliography</a>.</li><li>Before contributing, read <a href="https://github.com/byoungd/up/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING</a>, <a href="https://github.com/byoungd/up/blob/main/CONTRIBUTING.zh-CN.md" target="_blank" rel="noreferrer">中文贡献指南</a>, and the <a href="https://github.com/byoungd/up/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">Code of Conduct</a>.</li><li>Verification dates for products and services follow each page and <a href="https://github.com/byoungd/up/blob/main/ATTRIBUTIONS.md" target="_blank" rel="noreferrer">ATTRIBUTIONS</a>. Capabilities, availability, and compliance remain governed by official pages, formal agreements, and actual acceptance.</li></ul><p>Read online: <a href="https://byoungd.github.io/up/en/" target="_blank" rel="noreferrer">GitHub Pages</a> · <a href="https://github.com/byoungd/up" target="_blank" rel="noreferrer">GitHub repository</a> · Chinese edition: <a href="./../">人生进阶指南</a>.</p><p>If you do one thing today, create a <a href="./templates/learning-state">Learning State</a> page and write down the problem you face, the clues at hand, and the next smallest task. Do not wait for the road to widen before you start. Many roads appear only after the foot lands.</p>',7)])])}const v=s(c,[["render",u]]);export{k as __pageData,v as default};
